// components/DataTable.js
'use client';

import { useState } from 'react';
import { Search as SearchIcon } from '@mui/icons-material';

export default function DataTable({
  headers,
  data,
  renderRow,
  searchPlaceholder = "Search...",
  searchKeys = [],
}) {
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(5);

  const filteredData = data.filter(item =>
    searchKeys.some(key =>
      String(item[key]).toLowerCase().includes(searchQuery.toLowerCase())
    )
  );

  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = filteredData.slice(indexOfFirstItem, indexOfLastItem);
  const totalPages = Math.ceil(filteredData.length / itemsPerPage);

  return (
    <div className="space-y-4">
      <div className="relative w-full sm:w-96">
        <input
          type="text"
          placeholder={searchPlaceholder}
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="pl-10 pr-4 py-2 bg-white border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500 w-full shadow-sm"
        />
        <SearchIcon className="absolute left-3 top-2.5 text-gray-400" />
      </div>

      <div className="bg-white rounded-xl shadow-lg overflow-hidden">
        <div className="max-h-[500px] overflow-y-auto">
          <table className="w-full">
            <thead className="table-header">
              <tr>
                {headers.map((header, index) => (
                  <th key={index} className="table-cell">
                    {header}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {currentItems.map((item, index) => renderRow(item, index))}
            </tbody>
          </table>
        </div>

        <div className="flex justify-between items-center p-4 bg-gradient-to-r from-blue-50 to-gray-50">
          <select
            onChange={(e) => {
              setItemsPerPage(Number(e.target.value));
              setCurrentPage(1);
            }}
            value={itemsPerPage}
            className="border p-2 rounded-lg shadow-sm"
          >
            {[5, 10, 15].map(num => (
              <option key={num} value={num}>{num} per page</option>
            ))}
          </select>
          <div className="flex space-x-2">
            {Array.from({ length: totalPages }, (_, index) => (
              <button
                key={index}
                onClick={() => setCurrentPage(index + 1)}
                className={`px-4 py-2 text-sm rounded-lg ${
                  currentPage === index + 1 
                    ? 'bg-blue-600 text-white' 
                    : 'bg-white text-blue-600'
                }`}
              >
                {index + 1}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}